const items = $input.all().map(i => i.json);
const role = 'Ai / ML Engineer';
if (!items.length) { return [{ json: { role, skip: true } }]; }
const rows = items.map((c, i) => `<tr><td>${i + 1}</td><td>${c.Name || ''}</td><td>${c.Email || ''}</td><td>${c.Score || ''}</td><td>${c.GPA || ''}</td><td>${(c['Overall Reasoning'] || '').slice(0, 300)}</td></tr>`).join('');
const html = `<h2>Top candidates - ${role}</h2><p>Top ${items.length} by score (manual review required, no automatic winner).</p><table border="1" cellpadding="6" cellspacing="0"><tr><th>#</th><th>Name</th><th>Email</th><th>Score</th><th>GPA</th><th>Reasoning</th></tr>${rows}</table>`;
return [{ json: { role, skip: false, subject: `[HR] Top candidates - ${role}`, html } }];

