const repos = Array.isArray($json) ? $json : ($json.body || []);
let summary = 'No public repositories found.';
if (Array.isArray(repos) && repos.length) {
  const top = repos
    .filter(r => !r.fork)
    .sort((a, b) => (b.stargazers_count || 0) - (a.stargazers_count || 0))
    .slice(0, 15)
    .map(r => `- ${r.name} (${r.language || 'n/a'}, star ${r.stargazers_count || 0}): ${(r.description || '').slice(0, 120)}`);
  const langs = [...new Set(repos.map(r => r.language).filter(Boolean))];
  summary = `Public repos: ${repos.length}. Languages: ${langs.join(', ') || 'n/a'}.\nTop repos:\n${top.join('\n')}`;
}
return [{ json: { github_summary: summary } }];

const raw = $json.merged_response || ($json.content && $json.content[0] && $json.content[0].text) || '';
let parsed = {};
try {
  const cleaned = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  parsed = JSON.parse(cleaned.slice(start, end + 1));
} catch (e) {
  parsed = { score: 0, cv_fit_notes: 'Parse error', github_notes: '', gpa_contribution: '', overall_reasoning: 'Could not parse model output: ' + String(raw).slice(0, 300) };
}
const c = $('Loop Over Candidates').item.json;
return [{ json: {
  Name: c['Name'],
  Email: c['Email'],
  Phone: c['Phone'] || '',
  'Role Applied For': c['Role Applied For'],
  GPA: c['GPA'],
  'LinkedIn URL': c['LinkedIn URL'] || '',
  'GitHub URL': c['GitHub URL'] || '',
  row_number: c['row_number'],
  score: Number(parsed.score) || 0,
  cv_fit_notes: parsed.cv_fit_notes || '',
  github_notes: parsed.github_notes || '',
  gpa_contribution: parsed.gpa_contribution || '',
  overall_reasoning: parsed.overall_reasoning || '',
} }];

