const structured = analysis.structuredData || {};
return [{ json: {
  Name: structured.candidateName || call?.assistantOverrides?.variableValues?.candidateName || '',
  Phone: call?.customer?.number || '',
  PickedUp: structured.pickedUp === true || structured.pickedUp === 'true' ? 'Yes' : 'No',
  Notes: structured.notes || analysis.summary || ''
} }];
